<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Student Card · {{ $student['student_name'] }}</title>
<style>*{box-sizing:border-box}body{margin:0;background:#edf2f7;color:#07172d;font-family:Arial,sans-serif}.toolbar{max-width:760px;margin:24px auto 12px;display:flex;justify-content:space-between}.toolbar a,.toolbar button{border:0;border-radius:8px;padding:11px 15px;font-weight:800;text-decoration:none;cursor:pointer}.toolbar a{background:#fff}.toolbar button{background:#1769ff;color:#fff}.sheet{width:min(760px,calc(100% - 24px));margin:auto;background:#fff;border-radius:18px;overflow:hidden;box-shadow:0 18px 55px #07172d20}.head{padding:27px 32px;display:flex;justify-content:space-between;align-items:center;background:linear-gradient(120deg,#06182e,#1769ff);color:#fff}.brand{display:flex;gap:14px;align-items:center}.brand img{width:72px;height:72px;border-radius:50%;background:#fff}.brand h1{font-size:22px;margin:0}.brand p{margin:5px 0;color:#c9deed;font-size:11px}.head>div:last-child{text-align:right}.head small,.head b{display:block}.head small{color:#bcd3e5;font-size:9px;letter-spacing:1px}.head b{margin-top:7px}.content{padding:32px}.student-name{text-align:center;padding-bottom:24px;border-bottom:1px solid #dce4ea}.student-name small{color:#65798b;font-size:10px;letter-spacing:1px}.student-name h2{margin:8px 0 5px;font-size:28px}.student-name p{margin:0;color:#53697c}.details{display:grid;grid-template-columns:1fr 1fr;gap:18px 36px;padding:28px 0}.details div{border-bottom:1px solid #e5ebef;padding-bottom:12px}.details small,.details b{display:block}.details small{font-size:9px;color:#718599;text-transform:uppercase;margin-bottom:6px}.fees{display:grid;grid-template-columns:repeat(3,1fr);border:1px solid #dce4ea;border-radius:12px;overflow:hidden}.fees div{padding:16px;text-align:center;border-right:1px solid #dce4ea}.fees div:last-child{border:0}.fees small,.fees b{display:block}.fees small{font-size:9px;color:#718599;margin-bottom:7px}.fees .paid{background:#e9f8f0}.fees .balance{background:#fff6e7}.foot{display:flex;justify-content:space-between;gap:20px;margin-top:35px;padding-top:20px;border-top:1px dashed #aebdca;font-size:11px;color:#62778a}.signature{min-width:170px;text-align:center;border-top:1px solid #07172d;padding-top:7px}.note{text-align:center;background:#f3f6f9;padding:14px;color:#718599;font-size:10px}@media(max-width:600px){.details,.fees{grid-template-columns:1fr}.fees div{border-right:0;border-bottom:1px solid #dce4ea}.head,.foot{align-items:flex-start;flex-direction:column;gap:18px}.head>div:last-child{text-align:left}}@media print{body{background:#fff}.toolbar{display:none}.sheet{width:100%;box-shadow:none;border-radius:0}.head,.fees .paid,.fees .balance,.note{-webkit-print-color-adjust:exact;print-color-adjust:exact}}</style></head><body>
<div class="toolbar"><a href="{{ route('admin.students.index') }}">← Back to Students</a><button onclick="window.print()">Print / Save PDF</button></div>
<article class="sheet"><header class="head"><div class="brand"><img src="{{ asset('images/mci-logo.webp') }}" alt="MCI"><div><h1>Micro Computer Institute</h1><p>Education · Skill Development · Career</p></div></div><div><small>STUDENT ADMISSION CARD</small><b>{{ $student['application_no'] }}</b></div></header>
<div class="content"><section class="student-name"><small>ADMITTED STUDENT</small><h2>{{ $student['student_name'] }}</h2><p>{{ $course?->title ?? $student['course_code'] }}</p></section>
<section class="details"><div><small>Guardian Name</small><b>{{ $student['guardian_name'] }}</b></div><div><small>Date of Birth</small><b>{{ \Carbon\Carbon::parse($student['dob'])->format('d M Y') }}</b></div><div><small>Mobile Number</small><b>{{ $student['phone'] }}</b></div><div><small>Course Code</small><b>{{ $student['course_code'] }}</b></div><div><small>Roll Number</small><b>{{ $student['roll_no'] ?? '—' }}</b></div><div><small>Joining Date</small><b>{{ isset($student['joining_date']) ? \Carbon\Carbon::parse($student['joining_date'])->format('d M Y') : '—' }}</b></div><div><small>Course Duration</small><b>{{ $course?->duration ?? '—' }}</b></div><div><small>Batch</small><b>{{ $student['batch_name'] ?? '—' }}</b></div><div><small>Batch Timing</small><b>{{ $student['batch_time'] ?? $student['preferred_time'] ?: '—' }}</b></div><div><small>Student Status</small><b>{{ ucfirst($student['student_status'] ?? 'active') }}</b></div><div><small>Qualification</small><b>{{ $student['qualification'] }}</b></div><div><small>City</small><b>{{ $student['city'] }}</b></div></section>
<section class="fees"><div><small>COURSE FEE</small><b>₹{{ number_format((float)$student['course_fee'],2) }}</b></div><div class="paid"><small>PAID</small><b>₹{{ number_format((float)$student['paid_amount'],2) }}</b></div><div class="balance"><small>BALANCE</small><b>₹{{ number_format((float)$student['balance_amount'],2) }}</b></div></section>
<footer class="foot"><div>{{ $settings['address_line'] }}<br>{{ $settings['city'] }}, {{ $settings['district'] }}, {{ $settings['state'] }} – {{ $settings['pin'] }}<br>{{ $settings['phone'] }}</div><div class="signature">Authorised Signature</div></footer></div><div class="note">This card confirms admission in the course stated above. Please keep it safely.</div></article></body></html>
